// CubeGame.Features.Creatures — building geometry of a structure footprint (D3 step 3).
//
// Alpha evidence covers the DIMENSIONS only: W-17 house = 3×3×4 (AlphaStructureTemplates.HouseId), dungeon room
// = 3×3×3 with step 7. The voxels of Alpha's own houses are generated by world code that is not ported yet, so
// this builder produces a RECONSTRUCTED block house of the proven size: floor, four walls, one doorway
// (1×2) and a roof. It is NOT claimed to be Alpha's house — the provenance string says so, and the visual
// review (stage 3 of the plan) judges the look.
//
// The builder is pure: it writes through a delegate, so a test can verify the shape without a world.
using System;
using System.Collections.Generic;
using CubeGame.Features.World;

namespace CubeGame.Features.Creatures
{
    /// <summary>Reconstructed block geometry of a structure footprint (dimensions proven, voxels CubeGame's).</summary>
    public static class AlphaHouseBuilder
    {
        public const string Provenance =
            "RECONSTRUCTED_FROM_DIMENSIONS: W-17 footprint proven, Alpha house voxels not ported (not Alpha parity)";

        /// <summary>Door is one voxel wide and two voxels high on the given side (0 = -Z, 1 = +X, 2 = +Z, 3 = -X).</summary>
        public const int DoorWidth = 1;
        public const int DoorHeight = 2;

        // Alpha material flags: 1 = default solid, 3/6 = the flags the terrain passes use for wood/soil-like blocks.
        static readonly uint WallVoxel = Voxel.Pack(150, 145, 135, 1);
        static readonly uint FloorVoxel = Voxel.Pack(120, 85, 55, 3);
        static readonly uint RoofVoxel = Voxel.Pack(95, 70, 50, 3);

        /// <summary>Writes the house into the world; returns the number of voxels written.</summary>
        public static int Build(int originX, int originY, int originZ, int width, int depth, int height,
            Action<int, int, int, uint> write, int doorSide = 0)
        {
            if (write == null) throw new ArgumentNullException(nameof(write));
            if (width < 3 || depth < 3 || height < 3) throw new ArgumentOutOfRangeException(nameof(width),
                "a house needs at least 3×3×3 voxels");
            int count = 0;
            for (int x = 0; x < width; x++)
            for (int z = 0; z < depth; z++)
            {
                write(originX + x, originY, originZ + z, FloorVoxel);
                count++;
                write(originX + x, originY + height - 1, originZ + z, RoofVoxel);
                count++;
            }

            int doorX = width / 2;
            int doorZ = depth / 2;
            for (int y = 1; y < height - 1; y++)
            {
                for (int x = 0; x < width; x++)
                {
                    if (IsDoorway(doorSide, 0, x, y, doorX)) count += Write(write, originX + x, originY + y, originZ, WallVoxel);
                    if (IsDoorway(doorSide, 2, x, y, doorX)) count += Write(write, originX + x, originY + y, originZ + depth - 1, WallVoxel);
                }

                for (int z = 1; z < depth - 1; z++)
                {
                    if (IsDoorway(doorSide, 3, z, y, doorZ)) count += Write(write, originX, originY + y, originZ + z, WallVoxel);
                    if (IsDoorway(doorSide, 1, z, y, doorZ)) count += Write(write, originX + width - 1, originY + y, originZ + z, WallVoxel);
                }
            }

            return count;
        }

        /// <summary>True when this wall voxel is NOT written because the doorway of <paramref name="side"/> is there.</summary>
        static bool IsDoorway(int doorSide, int side, int along, int y, int doorMiddle)
        {
            if (side != doorSide) return true;
            if (y < 1 || y > DoorHeight) return true;
            int from = doorMiddle - (DoorWidth - 1) / 2;
            return along < from || along >= from + DoorWidth;
        }

        static int Write(Action<int, int, int, uint> write, int x, int y, int z, uint voxel)
        {
            write(x, y, z, voxel);
            return 1;
        }

        /// <summary>All voxels of a house, for tests and previews (same rule as <see cref="Build"/>).</summary>
        public static List<(int X, int Y, int Z, uint Voxel)> Voxels(int originX, int originY, int originZ,
            int width, int depth, int height, int doorSide = 0)
        {
            var result = new List<(int, int, int, uint)>();
            Build(originX, originY, originZ, width, depth, height,
                (x, y, z, v) => result.Add((x, y, z, v)), doorSide);
            return result;
        }

        /// <summary>
        /// Alpha house geometry (R7, B_house_research.md): a 3x3x4 grid whose cells carry part types
        /// (1 wall / 2 floor / 3 roof) plus door flags. Styles 1..5 fill different footprints
        /// (Chunk_generateObjects 0x5AF170): style 1 = 3x3, styles 2..5 = 2x2. The layout is
        /// ALPHA_DECOMPILED; the voxel materials remain RECONSTRUCTED (Alpha's part->material map is
        /// not ported yet), so this is honest geometry parity with partial materials.
        /// </summary>
        public const string AlphaProvenance =
            "ALPHA_DECOMPILED: house 3x3x4 part grid from Chunk_generateObjects 0x5AF170; materials RECONSTRUCTED";

        public static int BuildAlpha(int originX, int originY, int originZ, int style, int doorSide,
            Action<int, int, int, uint> write)
        {
            if (write == null) throw new ArgumentNullException(nameof(write));
            int footprint = style == 1 ? 3 : 2;   // style 1 = 3x3, styles 2..5 = 2x2
            int roofY = style == 1 ? 3 : 2;       // style 1 = 4 layers, styles 2..5 = 3 layers
            int count = 0;

            // Floor (part type 2) at y=0.
            for (int x = 0; x < footprint; x++)
            for (int z = 0; z < footprint; z++)
                count += Write(write, originX + x, originY, originZ + z, FloorVoxel);

            // Walls (part type 1) at y=1..roofY-1; the door flag renders as a doorway (no wall).
            int doorX = footprint / 2;
            for (int y = 1; y < roofY; y++)
            {
                for (int x = 0; x < footprint; x++)
                {
                    if (!(y <= DoorHeight && IsDoorway(doorSide, 0, x, y, doorX)))
                        count += Write(write, originX + x, originY + y, originZ, WallVoxel);
                    if (!(y <= DoorHeight && IsDoorway(doorSide, 2, x, y, doorX)))
                        count += Write(write, originX + x, originY + y, originZ + footprint - 1, WallVoxel);
                }

                for (int z = 1; z < footprint - 1; z++)
                {
                    if (!(y <= DoorHeight && IsDoorway(doorSide, 3, z, y, doorX)))
                        count += Write(write, originX, originY + y, originZ + z, WallVoxel);
                    if (!(y <= DoorHeight && IsDoorway(doorSide, 1, z, y, doorX)))
                        count += Write(write, originX + footprint - 1, originY + y, originZ + z, WallVoxel);
                }
            }

            // Roof (part type 3) at y=roofY.
            for (int x = 0; x < footprint; x++)
            for (int z = 0; z < footprint; z++)
                count += Write(write, originX + x, originY + roofY, originZ + z, RoofVoxel);

            return count;
        }
    }
}
